mapper.update:
UPDATE edu.attempt_question_results
SET is_correct = #{correct}, updated_at = NOW()
WHERE attempt_id = #{attemptId}
  AND question_id = #{questionId}

mapper.select:
SELECT result.attempt_id, attempt.quiz_id, result.question_id, result.kt_question_id, result.interaction_order, result.is_correct, result.learning_outcome_id, result.kt_learning_outcome_id, result.learning_outcome_mapping_count, attempt.submitted_time FROM edu.attempt_question_results result JOIN edu.attempts attempt ON attempt.id = result.attempt_id WHERE attempt.student_id = #{studentId} AND attempt.status = 'FINISHED' AND attempt.submitted_time IS NOT NULL AND result.is_correct IS NOT NULL AND attempt.quiz_id IN
#{quizId}
ORDER BY attempt.submitted_time, attempt.id, result.interaction_order
